package com.example.sortname.model;

import jakarta.persistence.*;
import lombok.*;

/**
 * Mirrors the EMPREC copybook layout (54 bytes total):
 *   EMP-ID    PIC X(5)   -> cols  1-5
 *   EMP-NAME  PIC X(25)  -> cols  6-30
 *   EMP-DEPT  PIC X(10)  -> cols 31-40
 *   EMP-SAL   PIC 9(9)V99 -> cols 41-51  (stored as numeric string, 11 chars)
 *   FILLER    PIC X(3)   -> cols 52-54
 */
@Entity
@Table(name = "employees")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Employee {

    @Id
    @Column(name = "emp_id", length = 5, nullable = false)
    private String empId;

    @Column(name = "emp_name", length = 25, nullable = false)
    private String empName;

    @Column(name = "emp_dept", length = 10)
    private String empDept;

    /** Stored as a plain numeric string to preserve COBOL PIC 9(9)V99 layout */
    @Column(name = "emp_sal", length = 11)
    private String empSal;
}

