package com.example.sortname.repository;

import com.example.sortname.model.Employee;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

import java.util.List;

@Repository
public interface EmployeeRepository extends JpaRepository<Employee, String> {

    /**
     * Equivalent to: SORT SORT-FILE ON ASCENDING KEY EMP-NAME
     * Spring Data derives ORDER BY emp_name ASC automatically.
     */
    List<Employee> findAllByOrderByEmpNameAsc();
}

