package com.example.sortname.service;

import com.example.sortname.model.Employee;
import com.example.sortname.repository.EmployeeRepository;
import com.example.sortname.util.EmployeeRecordParser;
import com.example.sortname.util.EmployeeRecordFormatter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Business-logic equivalent of SORTNAME.cbl PROCEDURE DIVISION.
 *
 * Flow (mirrors COBOL SORT verb with USING / GIVING):
 *   1. Read all 54-byte fixed-width records from the input file  (USING EMP-FILE)
 *   2. Upsert them into PostgreSQL                               (replaces SD SORT-FILE)
 *   3. Query back sorted ascending by EMP-NAME                   (ON ASCENDING KEY EMP-NAME)
 *   4. Write sorted records to the output file                   (GIVING OUT-FILE)
 *   5. Log completion message                                    (DISPLAY "SORTNAME: SORT COMPLETED")
 */
@Service
@RequiredArgsConstructor
@Slf4j
public class SortnameService {

    private final EmployeeRepository employeeRepository;

    @Value("${sortname.input.file:data/input/employees.dat}")
    private String inputFilePath;

    @Value("${sortname.output.file:data/output/sorted_by_name.dat}")
    private String outputFilePath;

    /**
     * Main entry point — mirrors MAIN-PARA.
     */
    @Transactional
    public void execute() throws IOException {
        List<Employee> employees = readInputFile();
        persistEmployees(employees);
        List<Employee> sorted = employeeRepository.findAllByOrderByEmpNameAsc();
        writeOutputFile(sorted);
        // DISPLAY "SORTNAME: SORT COMPLETED"
        log.info("SORTNAME: SORT COMPLETED");
    }

    // ------------------------------------------------------------------
    // Step 1 – Read fixed-width input file (USING EMP-FILE)
    // ------------------------------------------------------------------
    private List<Employee> readInputFile() throws IOException {
        Path path = Paths.get(inputFilePath);
        List<Employee> employees = new ArrayList<>();

        try (BufferedReader reader = Files.newBufferedReader(path, StandardCharsets.UTF_8)) {
            String line;
            int lineNumber = 0;
            while ((line = reader.readLine()) != null) {
                lineNumber++;
                // Pad or truncate to exactly 54 characters (EMP-IN PIC X(54))
                String record = padOrTruncate(line, 54);
                try {
                    Employee emp = EmployeeRecordParser.parse(record);
                    employees.add(emp);
                } catch (IllegalArgumentException e) {
                    log.warn("Skipping malformed record at line {}: {}", lineNumber, e.getMessage());
                }
            }
        }
        log.info("SORTNAME: Read {} record(s) from '{}'", employees.size(), inputFilePath);
        return employees;
    }

    // ------------------------------------------------------------------
    // Step 2 – Persist to PostgreSQL (replaces in-memory SORT work file)
    // ------------------------------------------------------------------
    private void persistEmployees(List<Employee> employees) {
        employeeRepository.saveAll(employees);
        log.info("SORTNAME: Persisted {} record(s) to database", employees.size());
    }

    // ------------------------------------------------------------------
    // Step 4 – Write sorted output file (GIVING OUT-FILE)
    // ------------------------------------------------------------------
    private void writeOutputFile(List<Employee> sorted) throws IOException {
        Path path = Paths.get(outputFilePath);
        Files.createDirectories(path.getParent());

        try (BufferedWriter writer = Files.newBufferedWriter(path, StandardCharsets.UTF_8,
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
            for (Employee emp : sorted) {
                // EMP-OUT PIC X(54) — format back to fixed-width
                writer.write(EmployeeRecordFormatter.format(emp));
                writer.newLine();
            }
        }
        log.info("SORTNAME: Wrote {} sorted record(s) to '{}'", sorted.size(), outputFilePath);
    }

    // ------------------------------------------------------------------
    // Helper
    // ------------------------------------------------------------------
    private static String padOrTruncate(String s, int length) {
        if (s.length() >= length) {
            return s.substring(0, length);
        }
        return String.format("%-" + length + "s", s);
    }
}

