package com.example.sortname.util;

import com.example.sortname.model.Employee;

/**
 * Parses a 54-byte fixed-width string produced by the EMPREC copybook.
 *
 * Assumed EMPREC layout (54 bytes):
 *   Pos  1- 5  (len  5) : EMP-ID
 *   Pos  6-30  (len 25) : EMP-NAME
 *   Pos 31-40  (len 10) : EMP-DEPT
 *   Pos 41-51  (len 11) : EMP-SAL  (PIC 9(9)V99 stored as 11-char string)
 *   Pos 52-54  (len  3) : FILLER
 */
public final class EmployeeRecordParser {

    private EmployeeRecordParser() {}

    public static Employee parse(String record) {
        if (record == null || record.length() < 54) {
            throw new IllegalArgumentException(
                    "Record must be exactly 54 characters, got: " + (record == null ? 0 : record.length()));
        }

        String empId   = record.substring(0,  5).trim();
        String empName = record.substring(5,  30).trim();
        String empDept = record.substring(30, 40).trim();
        String empSal  = record.substring(40, 51).trim();
        // FILLER bytes 52-54 are intentionally ignored

        if (empId.isEmpty()) {
            throw new IllegalArgumentException("EMP-ID is blank — cannot be a primary key");
        }

        return Employee.builder()
                .empId(empId)
                .empName(empName)
                .empDept(empDept)
                .empSal(empSal)
                .build();
    }
}

