package com.example.sortname.util;

import com.example.sortname.model.Employee;

/**
 * Formats an Employee back into the 54-byte fixed-width layout
 * used by the GIVING OUT-FILE clause (EMP-OUT PIC X(54)).
 */
public final class EmployeeRecordFormatter {

    private EmployeeRecordFormatter() {}

    public static String format(Employee emp) {
        String id   = padRight(emp.getEmpId(),   5);
        String name = padRight(emp.getEmpName(), 25);
        String dept = padRight(emp.getEmpDept(), 10);
        String sal  = padLeft (emp.getEmpSal(),  11);  // numeric field — right-align / zero-fill
        String fill = "   ";                            // 3-byte FILLER
        return id + name + dept + sal + fill;
    }

    private static String padRight(String value, int width) {
        if (value == null) value = "";
        if (value.length() >= width) return value.substring(0, width);
        return String.format("%-" + width + "s", value);
    }

    private static String padLeft(String value, int width) {
        if (value == null) value = "";
        if (value.length() >= width) return value.substring(0, width);
        return String.format("%" + width + "s", value).replace(' ', '0');
    }
}

