package com.example.sortname.runner;

import com.example.sortname.service.SortnameService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

/**
 * CommandLineRunner acts as the program entry point,
 * equivalent to the STOP RUN at the end of MAIN-PARA.
 */
@Component
@RequiredArgsConstructor
@Slf4j
public class SortnameRunner implements CommandLineRunner {

    private final SortnameService sortnameService;

    @Override
    public void run(String... args) {
        try {
            sortnameService.execute();
        } catch (Exception e) {
            log.error("SORTNAME: ABEND — {}", e.getMessage(), e);
            System.exit(1);   // mirror COBOL abnormal termination
        }
    }
}

