# application.yml
spring:
  application:
    name: sortname

  datasource:
    url: jdbc:postgresql://localhost:5432/sortname_db
    username: ${DB_USERNAME:postgres}
    password: ${DB_PASSWORD:postgres}
    driver-class-name: org.postgresql.Driver
    hikari:
      maximum-pool-size: 5
      connection-timeout: 30000

  jpa:
    hibernate:
      ddl-auto: validate          # schema managed by Flyway
    show-sql: false
    properties:
      hibernate:
        dialect: org.hibernate.dialect.PostgreSQLDialect
        format_sql: true

  flyway:
    enabled: true
    locations: classpath:db/migration

sortname:
  input:
    file: data/input/employees.dat
  output:
    file: data/output/sorted_by_name.dat

logging:
  level:
    com.example.sortname: INFO

