-- Creates the EMPLOYEES table that backs the SD SORT-FILE work area.

CREATE TABLE IF NOT EXISTS employees (
    emp_id   VARCHAR(5)  NOT NULL,
    emp_name VARCHAR(25) NOT NULL,
    emp_dept VARCHAR(10),
    emp_sal  VARCHAR(11),
    CONSTRAINT pk_employees PRIMARY KEY (emp_id)
);

CREATE INDEX IF NOT EXISTS idx_employees_emp_name
    ON employees (emp_name ASC);   -- supports ORDER BY EMP-NAME ASC

