package com.example.sortname.service;

import com.example.sortname.model.Employee;
import com.example.sortname.repository.EmployeeRepository;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.mockito.*;

import java.io.IOException;
import java.nio.file.*;
import java.util.List;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class SortnameServiceTest {

    @TempDir
    Path tempDir;

    @Mock
    EmployeeRepository employeeRepository;

    @InjectMocks
    SortnameService sortnameService;

    @BeforeEach
    void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    @DisplayName("execute() reads input, persists, sorts by name, writes output")
    void testExecute() throws IOException {
        // --- arrange input file ---
        Path inputDir = tempDir.resolve("data/input");
        Files.createDirectories(inputDir);
        Path inputFile = inputDir.resolve("employees.dat");

        // 54-byte records: ID(5) NAME(25) DEPT(10) SAL(11) FILL(3)
        String rec1 = "00002Zebra, Arthur           HR        0000012500   ";
        String rec2 = "00001Adams, Betty            IT        0000098000   ";
        Files.writeString(inputFile, rec1 + System.lineSeparator() + rec2 + System.lineSeparator());

        // inject paths via reflection
        setField(sortnameService, "inputFilePath",  inputFile.toString());
        Path outputFile = tempDir.resolve("data/output/sorted_by_name.dat");
        setField(sortnameService, "outputFilePath", outputFile.toString());

        // repository returns records in name-sorted order
        Employee emp1 = Employee.builder()
                .empId("00001").empName("Adams, Betty").empDept("IT").empSal("0000098000").build();
        Employee emp2 = Employee.builder()
                .empId("00002").empName("Zebra, Arthur").empDept("HR").empSal("0000012500").build();
        when(employeeRepository.saveAll(any())).thenReturn(List.of(emp1, emp2));
        when(employeeRepository.findAllByOrderByEmpNameAsc()).thenReturn(List.of(emp1, emp2));

        // --- act ---
        sortnameService.execute();

        // --- assert ---
        verify(employeeRepository, times(1)).saveAll(argThat(list -> {
            List<?> l = (List<?>) list;
            return l.size() == 2;
        }));
        verify(employeeRepository, times(1)).findAllByOrderByEmpNameAsc();

        assertThat(outputFile).exists();
        List<String> lines = Files.readAllLines(outputFile);
        assertThat(lines).hasSize(2);
        // First sorted record should be Adams, Betty
        assertThat(lines.get(0)).contains("Adams, Betty");
    }

    // ------------------------------------------------------------------
    private static void setField(Object target, String fieldName, Object value)
            throws IOException {
        try {
            var field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (ReflectiveOperationException e) {
            throw new IOException("Cannot set field " + fieldName, e);
        }
    }
}
